  induction c using limitRecOn with;
  | H₁ => simp only [succ_zero, mul_one];
  | H₂ c IH => rw [mul_succ, IH, ← add_assoc, add_assoc _ b, ba, ← mul_succ];
  | H₃ c l IH => rw [mul_succ, add_mul_limit_aux ba l IH, mul_succ, add_assoc];

